import request from '@/utils/request'
import { useUserStore } from '@/store/user'

const BASE = '/api/rag'
const checked = async (promise) => {
  const result = await promise
  if (result?.code && String(result.code) !== '200') throw new Error(result.msg || result.message || '知识库请求失败')
  return result
}
export const listKnowledgeBases = (params = {}) => checked(request.get(`${BASE}/knowledge-bases`, { params }))
export const createKnowledgeBase = (data) => checked(request.post(`${BASE}/knowledge-bases`, data))
export const updateKnowledgeBase = (id, data) => checked(request.put(`${BASE}/knowledge-bases/${id}`, data))
export const deleteKnowledgeBase = (id) => checked(request.delete(`${BASE}/knowledge-bases/${id}`))
export const listDocuments = (id, limit = 100, offset = 0) => checked(request.get(`${BASE}/knowledge-bases/${id}/documents`, { params: { limit, offset } }))
export const getDocument = (id) => checked(request.get(`${BASE}/documents/${id}`))
export const deleteDocument = (id) => checked(request.delete(`${BASE}/documents/${id}`))
export const getDocumentChunks = (id) => checked(request.get(`${BASE}/documents/${id}/chunks`))
export const getChunk = (id) => checked(request.get(`${BASE}/chunks/${id}`))
export const downloadDocument = (id) => request.get(`${BASE}/documents/${id}/download`, { responseType: 'blob' })
export const uploadDocument = (id, file, config = {}) => {
  const body = new FormData()
  body.append('file', file)
  return checked(request.post(`${BASE}/knowledge-bases/${id}/documents`, body, { timeout: 180000, ...config }))
}
export const search = (data, config = {}) => checked(request.post(`${BASE}/search`, {
  knowledgeBaseIds: data.knowledgeBaseIds || data.kbIds || [],
  query: data.query,
  topK: data.topK || data.limit || 8
}, { silentError:true, ...config }))
export const chat = (data, config = {}) => checked(request.post(`${BASE}/chat`, data, { timeout: 120000, ...config }))
export const createSession = (data) => checked(request.post(`${BASE}/sessions`, data))
export const listSessions = () => checked(request.get(`${BASE}/sessions`))
export const getSessionMessages = (id) => checked(request.get(`${BASE}/sessions/${id}/messages`))
export const deleteSession = (id) => checked(request.delete(`${BASE}/sessions/${id}`))

// POST SSE: handle frame boundaries, CRLF, split UTF-8, and multiple data lines.
export function streamChat(data, callbacks = {}) {
  const controller = new AbortController()
  const token = [REDACTED]
  const endpoint = `${import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080'}${BASE}/chat/stream`
  const finished = (async () => {
    let complete = false
    try {
      const response = await fetch(endpoint, {
        method: 'POST', signal: controller.signal,
        headers: { 'Content-Type': 'application/json', Accept: 'text/event-stream', ...(token ? { Authorization: `Bearer ${token}` } : {}) },
        body: JSON.stringify(data)
      })
      if (!response.ok) {
        const payload = await response.json().catch(() => ({}))
        throw new Error(payload.msg || payload.message || (response.status === 401 ? '登录已过期，请重新登录' : `问答请求失败（${response.status}）`))
      }
      if (!response.headers.get('content-type')?.includes('text/event-stream')) {
        const result = await response.json().catch(() => null)
        throw new Error(result?.msg || result?.message || '问答服务未返回流式响应')
      }
      const reader = response.body?.getReader()
      if (!reader) throw new Error('无法读取问答响应')
      const decoder = new TextDecoder()
      let buffer = ''
      const processFrame = (frame) => {
        const lines = frame.split('\n')
        const event = lines.find(line => line.startsWith('event:'))?.slice(6).trim() || 'message'
        const raw = lines.filter(line => line.startsWith('data:')).map(line => line.slice(5).trimStart()).join('\n')
        if (!raw || raw === '[DONE]') return
        let payload
        try { payload = JSON.parse(raw) } catch { throw new Error('问答响应格式异常，请重试') }
        if (event === 'error') throw new Error(payload.message || payload.error || '问答生成失败')
        if (event === 'progress') callbacks.onProgress?.(payload)
        else if (event === 'delta') callbacks.onDelta?.(payload)
        else if (event === 'complete') {
          complete = true
          callbacks.onComplete?.(payload)
        }
      }
      while (true) {
        const { done, value } = await reader.read()
        buffer += done ? decoder.decode() : decoder.decode(value, { stream: true })
        // Concatenate first: CR and LF may be split between network reads.
        buffer = buffer.replace(/\r\n/g, '\n')
        let end
        while ((end = buffer.indexOf('\n\n')) >= 0) {
          processFrame(buffer.slice(0, end))
          buffer = buffer.slice(end + 2)
          if (complete) break
        }
        if (complete) {
          await reader.cancel().catch(() => {})
          callbacks.onDone?.()
          return
        }
        if (done) {
          if (buffer.trim()) processFrame(buffer)
          break
        }
      }
      if (!complete) throw new Error('连接中断，回答尚未完成，请重试')
      callbacks.onDone?.()
    } catch (error) {
      if (controller.signal.aborted) callbacks.onCancel?.()
      else callbacks.onError?.(error)
    }
  })()
  return { abort: () => controller.abort(), finished }
}

export function unwrapRag(result) { return result?.data ?? result }
export function ragList(result) {
  const data = unwrapRag(result)
  return Array.isArray(data) ? data : data?.data || data?.items || data?.records || []
}
import { ref, readonly, reactive, onBeforeUnmount } from 'vue'
import { ElMessage } from 'element-plus'
import * as rag from '@/api/rag'
import * as agentApi from '@/api/agent'

const messageOf = (error, fallback) => error?.response?.data?.msg || error?.response?.data?.message || error?.message || fallback

export function useNativeRag() {
  const messages = ref([])
  const sessions = ref([])
  const knowledgeBases = ref([])
  const loading = ref(false)
  const generating = ref(false)
  const currentSessionId = ref(null)
  const currentAgentSessionId = ref(null)
  const currentKbId = ref(null)
  const error = ref(null)
  const progress = ref('')
  let activeRequest = null
  let sessionVersion = 0

  function cancel() { activeRequest?.abort() }
  function resetKnowledgeContext(knowledgeBaseId) {
    cancel()
    sessionVersion++
    currentSessionId.value = null
    currentKbId.value = knowledgeBaseId || null
    messages.value = []
    error.value = null
  }
  onBeforeUnmount(cancel)

  async function loadKnowledgeBases() {
    try {
      knowledgeBases.value = rag.ragList(await rag.listKnowledgeBases())
      return knowledgeBases.value
    } catch (e) {
      error.value = messageOf(e, '加载知识库失败')
      ElMessage.error(error.value)
      return []
    }
  }
  async function createNewSession(knowledgeBaseId, title = '新对话') {
    resetKnowledgeContext(knowledgeBaseId)
    const version = sessionVersion
    if (!knowledgeBaseId) return null
    try {
      const data = rag.unwrapRag(await rag.createSession({ knowledgeBaseId, title }))
      if (version !== sessionVersion) return null
      currentSessionId.value = data.id
      return data.id
    } catch (e) {
      error.value = messageOf(e, '创建对话失败')
      ElMessage.error(error.value)
      return null
    }
  }
  async function loadSessions() {
    try {
      sessions.value = rag.ragList(await rag.listSessions())
      return sessions.value
    } catch (e) {
      error.value = messageOf(e, '加载对话失败')
      return []
    }
  }
  async function restoreSession(session) {
    cancel()
    const version = ++sessionVersion
    const list = rag.ragList(await rag.getSessionMessages(session.id))
    if (version !== sessionVersion) return
    currentSessionId.value = session.id
    currentKbId.value = session.knowledgeBaseId || session.kb_id || currentKbId.value
    messages.value = list
  }
  async function removeSession(id) {
    await rag.deleteSession(id)
    sessions.value = sessions.value.filter(session => session.id !== id)
    if (currentSessionId.value === id) {
      cancel()
      currentSessionId.value = null
      messages.value = []
    }
  }
  async function createNewAgentSession(title = '智能助手对话') {
    cancel()
    const data = rag.unwrapRag(await agentApi.createAgentSession({ agentId: 1, title }))
    currentAgentSessionId.value = data?.id || null
    messages.value = []
    return currentAgentSessionId.value
  }
  async function sendAgentMessage(query, displayContent) {
    if (!currentAgentSessionId.value) await createNewAgentSession()
    const controller = new AbortController()
    activeRequest = controller
    const message = reactive({ role: 'assistant', content: '', streaming: true, citations: [] })
    messages.value.push({ role: 'user', content: displayContent || query }, message)
    loading.value = generating.value = true
    error.value = null
    progress.value = '正在处理任务…'
    try {
      const data = rag.unwrapRag(await agentApi.sendAgentMessage(currentAgentSessionId.value, { content: query }, { signal: controller.signal, timeout: 120000, silent:true }))
      message.content = data?.content || data?.reply || data?.answer || ''
      message.pendingAction = data?.pendingAction || data?.pending_action || null
      message.citations = data?.citations || []
      message.status = data?.knowledgeStatus || data?.status || 'complete'
      message.warning = data?.knowledgeWarning || data?.warning || ''
      return message.content
    } catch (e) {
      if (controller.signal.aborted) message.status = 'cancelled'
      else {
        message.error = true
        message.errorMessage = error.value = messageOf(e, '任务处理失败，请重试')
        throw e
      }
      return ''
    } finally {
      message.streaming = false
      if (activeRequest === controller) {
        activeRequest = null
        loading.value = generating.value = false
        progress.value = ''
      }
    }
  }
  function sendMessage(mode, query, displayContent = query) {
    if (generating.value) return Promise.reject(new Error('请等待当前回答完成或先停止生成'))
    if (mode === 'agent') return sendAgentMessage(query, displayContent)
    if (!currentKbId.value) return Promise.reject(new Error('请先选择知识库'))
    const message = reactive({ role: 'assistant', content: '', streaming: true, citations: [], status: 'generating' })
    messages.value.push({ role: 'user', content: displayContent }, message)
    loading.value = generating.value = true
    progress.value = '正在检索资料…'
    error.value = null
    const version = sessionVersion
    return new Promise((resolve, reject) => {
      let settled = false
      let requestHandle
      const finish = () => {
        settled = true
        message.streaming = false
        if (activeRequest === requestHandle) {
          loading.value = generating.value = false
          progress.value = ''
          activeRequest = null
        }
      }
      requestHandle = rag.streamChat({ query, sessionId: currentSessionId.value, knowledgeBaseIds: [currentKbId.value] }, {
        onProgress: data => { if (version === sessionVersion) progress.value = data.message || '正在处理…' },
        onDelta: data => { message.content += data.content || '' },
        onComplete: data => {
          message.content = data.answer || ''
          message.citations = Array.isArray(data.citations) ? data.citations : []
          message.mode = data.mode
          message.status = data.status || 'complete'
          message.warning = data.warning || ''
          if (version === sessionVersion) currentSessionId.value = data.sessionId || currentSessionId.value
        },
        onDone: () => { if (!settled) { finish(); resolve(message.content) } },
        onCancel: () => {
          if (settled) return
          message.status = 'cancelled'
          message.citations = []
          finish()
          resolve('')
        },
        onError: e => {
          if (settled) return
          message.error = true
          message.status = 'error'
          message.errorMessage = messageOf(e, '回答生成失败，请重试')
          if (version === sessionVersion) error.value = message.errorMessage
          finish()
          reject(e)
        }
      })
      activeRequest = requestHandle
    })
  }
  async function searchInKB(knowledgeBaseIds, query) { return rag.unwrapRag(await rag.search({ knowledgeBaseIds, query })) }
  async function uploadToKB(id, file) { return rag.unwrapRag(await rag.uploadDocument(id, file)) }

  return {
    messages, sessions, knowledgeBases, loading, generating, currentSessionId, currentAgentSessionId, currentKbId,
    error: readonly(error), progress: readonly(progress), cancel, resetKnowledgeContext, loadKnowledgeBases, createNewSession,
    createNewAgentSession, loadSessions, restoreSession, removeSession, searchInKB, sendMessage, uploadToKB
  }
}
